export function getItemThumbnail(thumbPath: string, styleSlug: string, itemIndex: number): string | null {
  // Extract filename without ext
  const cleanName = thumbPath.split("/").pop()?.replace(".png", "") || "";
  if (EMBEDDED_ITEM_THUMBNAILS[cleanName]) return EMBEDDED_ITEM_THUMBNAILS[cleanName];
  const fallbackKey = `${styleSlug}_${itemIndex + 1}_`;
  const found = Object.keys(EMBEDDED_ITEM_THUMBNAILS).find(k => k.startsWith(fallbackKey));
  if (found) return EMBEDDED_ITEM_THUMBNAILS[found];
  return null;
}
